    try:
            
        zip_buffer = BytesIO()
        with zipfile.ZipFile(zip_buffer, 'w') as zip_file:
            csv_buffer = StringIO()
            writer = csv.writer(csv_buffer)            # Write CSV header
            writer.writerow(['Transformer Name', 'Owner', 'Serial Number', 'Description', 'Captured Date', 
                                'Category', 'Type', 'Senatorial District', 
                                'Address','Lat', 'Long'])
            
            # Write CSV rows
            for advance in results:
                writer.writerow([
                    advance['name'],
                    advance['owner'],
                    advance['serial_number'],
                    advance['description'],
                    advance['date'],
                    advance['category'],
                    advance['type'],
                    advance['district'],
                    advance['address'],
                    advance['lat'],
                    advance['long'],
                ])
                
                # Write the images to the zip file
                if advance['image']:
                    try:
                        if 'https' in advance['image']:
                            res = requests.get(advance['image'])
                            if res.status_code == 200:
                                zip_file.writestr(f'receipts/{advance["image"].split("/")[-1]}', res.content)
                        
                    except Exception as e:
                        print(f"Error adding receipt for advance ID {advance['id']}: {e}")
                
            # Write the CSV file to the zip
            zip_file.writestr(f'omachi_asset_capturing_exercise.csv', csv_buffer.getvalue())

        response = HttpResponse(zip_buffer.getvalue(), content_type='application/zip')
        response['Content-Disposition'] = f'attachment; filename="omachi_asset_capturing_exercise.zip"'
        return response
    except ValueError:
        print( 'Invalid date format. Please use YYYY-MM-DD.')
        return HttpResponse('Invalid date format. Please use YYYY-MM-DD.')
